import sys
import re
import heapq
import collections
import time

def parse_pddl_content(content):
    # Remove comments
    content = re.sub(r';.*$', '', content, flags=re.MULTILINE)
    # Tokenize
    tokens = re.findall(r'\(|\)|[^\s()]+', content)

    def parse_expr(token_iter):
        expr = []
        for token in token_iter:
            if token == '(':
                expr.append(parse_expr(token_iter))
            elif token == ')':
                return expr
            else:
                expr.append(token)
        return expr[0] if expr else []

    try:
        return parse_expr(iter(tokens))
    except StopIteration:
        return []

class Action:
    def __init__(self, name, params, precond, effect):
        self.name = name
        self.params = params
        self.precond = precond
        self.effect = effect

def get_subtree(tree, name):
    for node in tree:
        if isinstance(node, list) and len(node) > 0 and node[0] == name:
            return node
    return None

def parse_domain(domain_file):
    with open(domain_file, 'r') as f:
        content = f.read()
    tree = parse_pddl_content(content)
    # tree is list of top-level elements. Usually (define ...) is the first.
    # The parser returns the first expression.
    # So tree is ['define', ['domain', ...], ...]

    actions = []

    # We iterate over the children of 'define'
    if not tree or tree[0] != 'define':
        print("Invalid domain file")
        return []

    for item in tree:
        if isinstance(item, list) and len(item) > 0 and item[0] == ':action':
            name = item[1]
            params = []
            precond = []
            effect = []

            i = 2
            while i < len(item):
                key = item[i]
                val = item[i+1]
                if key == ':parameters':
                    params = val
                elif key == ':precondition':
                    precond = val
                elif key == ':effect':
                    effect = val
                i += 2
            actions.append(Action(name, params, precond, effect))

    return actions

def parse_problem(problem_file):
    with open(problem_file, 'r') as f:
        content = f.read()
    tree = parse_pddl_content(content)

    objects = []
    init = []
    goal = []

    if not tree or tree[0] != 'define':
        return [], [], []

    for item in tree:
        if isinstance(item, list) and len(item) > 0:
            if item[0] == ':objects':
                objects = item[1:]
            elif item[0] == ':init':
                init = item[1:]
            elif item[0] == ':goal':
                goal = item[1]

    return objects, init, goal

def subst_preds(preds, mapping):
    if isinstance(preds, list):
        if len(preds) == 0: return []
        if preds[0] in mapping:
            # This logic is for when param is used as a function/predicate head? No.
            # Predicates are (pred arg1 arg2).
            # Mapping is {'?a': 'plane1'}
            pass

        new_list = []
        for item in preds:
            new_list.append(subst_preds(item, mapping))
        return new_list
    elif isinstance(preds, str):
        return mapping.get(preds, preds)
    return preds

def check_preconds(preconds, state_facts):
    if not preconds: return True

    if preconds[0] == 'and':
        for p in preconds[1:]:
            if not check_single_precond(p, state_facts):
                return False
        return True
    else:
        return check_single_precond(preconds, state_facts)

def check_single_precond(p, state_facts):
    if not p: return True
    if p[0] == 'not':
        inner = p[1]
        fact_str = " ".join(inner)
        return fact_str not in state_facts
    else:
        fact_str = " ".join(p)
        return fact_str in state_facts

def apply_effects(effects, state_set):
    if not effects: return
    if effects[0] == 'and':
        effs = effects[1:]
    else:
        effs = [effects]

    for e in effs:
        if not e: continue
        if e[0] == 'not':
            inner = e[1]
            fact_str = " ".join(inner)
            if fact_str in state_set:
                state_set.remove(fact_str)
        else:
            fact_str = " ".join(e)
            state_set.add(fact_str)

def check_goal(state, goal_facts):
    return goal_facts.issubset(state)

def flatten_logic(logic_struct):
    if not isinstance(logic_struct, list): return []
    if not logic_struct: return []
    if logic_struct[0] == 'and':
        res = []
        for child in logic_struct[1:]:
            res.extend(flatten_logic(child))
        return res
    return [logic_struct]

def solve(domain_file, problem_file, output_file):
    actions = parse_domain(domain_file)
    p_objects, p_init, p_goal = parse_problem(problem_file)

    airplanes = set()
    for fact in p_init:
        if fact[0] == 'has-type':
            airplanes.add(fact[1])
    airplanes = sorted(list(airplanes))

    init_facts = set()
    for fact in p_init:
        fact_str = " ".join(fact)
        init_facts.add(fact_str)

    goal_facts = set()
    if p_goal[0] == 'and':
        for pred in p_goal[1:]:
            goal_facts.add(" ".join(pred))
    else:
        goal_facts.add(" ".join(p_goal))

    grounded_actions = []
    for act in actions:
        param_names = [p for p in act.params if p.startswith('?')]
        if len(param_names) == 1:
            param_name = param_names[0]
            for plane in airplanes:
                new_pre = subst_preds(act.precond, {param_name: plane})
                new_eff = subst_preds(act.effect, {param_name: plane})
                grounded_actions.append({
                    'name': act.name,
                    'args': [plane],
                    'pre': new_pre,
                    'eff': new_eff
                })
        else:
             # Handle 0 params or >1 if needed. Airport usually 1.
             if len(param_names) == 0:
                 grounded_actions.append({
                    'name': act.name,
                    'args': [],
                    'pre': act.precond,
                    'eff': act.effect
                 })

    # Optimization: actions by segment
    actions_by_seg = collections.defaultdict(list)
    # Also actions that don't depend on location (rare here)
    global_actions = []

    for ga in grounded_actions:
        seg = None
        # Look for (at-segment ?a SEG)
        # Assuming args[0] is ?a
        plane = ga['args'][0] if ga['args'] else None

        pre_list = flatten_logic(ga['pre'])
        for p in pre_list:
            if p[0] == 'at-segment' and p[1] == plane:
                seg = p[2]
                break

        if seg:
            actions_by_seg[seg].append(ga)
        else:
            global_actions.append(ga)

    # Heuristic Graph
    adj = collections.defaultdict(list)
    for act in actions:
        if act.name.startswith('move_'):
             # Extract from ungrounded structure
             # params: ?a
             # pre: (at-segment ?a FROM)
             # eff: (at-segment ?a TO)
             param_name = act.params[0] # ?a

             src = None
             dst = None

             pre_list = flatten_logic(act.precond)
             for p in pre_list:
                 if p[0] == 'at-segment' and p[1] == param_name:
                     src = p[2]

             eff_list = flatten_logic(act.effect)
             for p in eff_list:
                 if p[0] == 'at-segment' and p[1] == param_name:
                     dst = p[2]

             if src and dst:
                 adj[src].append(dst)

    heuristic_cache = {}
    def bfs_dist(start_node):
        dists = {}
        q = collections.deque([(start_node, 0)])
        dists[start_node] = 0
        while q:
            u, d = q.popleft()
            for v in adj[u]:
                if v not in dists:
                    dists[v] = d + 1
                    q.append((v, d+1))
        return dists

    def heuristic(state_facts):
        current_locs = {}
        for f in state_facts:
            parts = f.split()
            if parts[0] == 'at-segment':
                current_locs[parts[1]] = parts[2]

        h = 0
        for g in goal_facts:
            parts = g.split()
            # (is-parked plane seg) or (airborne plane seg)
            if parts[0] == 'is-parked':
                plane = parts[1]
                target = parts[2]
                if plane in current_locs:
                    curr = current_locs[plane]
                    if curr != target:
                        if curr not in heuristic_cache:
                            heuristic_cache[curr] = bfs_dist(curr)
                        h += heuristic_cache[curr].get(target, 100)
            elif parts[0] == 'airborne':
                plane = parts[1]
                target = parts[2]
                # airborne means it reached target and took off?
                # Check logic: (airborne ?a ?s) effect of takeoff
                # Takeoff requires (at-segment ?a ?s).
                # So goal is effectively reach ?s then +1 step.
                if f"airborne {plane} {target}" not in state_facts:
                    if plane in current_locs:
                        curr = current_locs[plane]
                        if curr != target:
                            if curr not in heuristic_cache:
                                heuristic_cache[curr] = bfs_dist(curr)
                            h += heuristic_cache[curr].get(target, 100)
                        else:
                            h += 1 # need to take off
        return h

    start_state = frozenset(init_facts)
    queue = [(heuristic(start_state), 0, start_state, [])]
    visited = {start_state: 0}

    start_time = time.time()

    while queue:
        f_val, g, state, plan = heapq.heappop(queue)

        if check_goal(state, goal_facts):
            with open(output_file, 'w') as out:
                for action_name, action_args in plan:
                    out.write(f"({action_name} {' '.join(action_args)})\n")
            return

        if time.time() - start_time > 180:
            print("Timeout")
            break

        current_planes = {}
        for fact in state:
            parts = fact.split()
            if parts[0] == 'at-segment':
                current_planes[parts[1]] = parts[2]

        # Generate successors
        # Collect all applicable actions for all planes
        for plane, seg in current_planes.items():
            candidates = actions_by_seg.get(seg, []) + global_actions
            for ga in candidates:
                if ga['args'] and ga['args'][0] != plane: continue

                if check_preconds(ga['pre'], state):
                    new_state_set = set(state)
                    apply_effects(ga['eff'], new_state_set)
                    new_state = frozenset(new_state_set)

                    new_g = g + 1
                    if new_state not in visited or new_g < visited[new_state]:
                        visited[new_state] = new_g
                        h = heuristic(new_state)
                        heapq.heappush(queue, (new_g + h, new_g, new_state, plan + [(ga['name'], ga['args'])]))

    print("No solution found or timeout")

if __name__ == "__main__":
    solve(sys.argv[1], sys.argv[2], sys.argv[3])

